use std::fs
use std::env

fn emit(text: string, number: bool, n: int) -> int {
    let mut count = n
    if number {
        for line in text.lines() {
            count += 1
            println("${count:>6}\t${line}")
        }
    } else {
        print(text)
    }
    count
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut count = 0
    let mut failed = false
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        count = emit(text, number, count)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(text) => { count = emit(text, number, count) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    failed = true
                }
            }
        }
    }
    if failed {
        std::process::exit(1)
    }
}

